<?php
$activeMenu='alarm';require_once __DIR__.'/../Config/database.php';require_once __DIR__.'/../Config/mikrotik.php';require_once __DIR__.'/../library/routeros_api.class.php';require_once __DIR__.'/alarm_engine.php';$db=new Database();$pdo=$db->connect();$mikrotikConfig=new MikroTikConfig();$router=$mikrotikConfig->getRouter();if($router){$api=new RouterosAPI();$api->debug=false;$api->port=(int)$router['api_port'];if($api->connect($router['ip_address'],$router['username'],$router['password'])){$engine=new AlarmEngine();$engine->routerOnline($router['id']);$mikrotikConfig->updateStatus($router['id'],'ONLINE');$api->disconnect();}}$sql="SELECT id,router_id,interface_name,alarm_type,severity,message,value,threshold,status,created_at,resolved_at FROM alarms ORDER BY created_at DESC LIMIT 100";$st=$pdo->prepare($sql);$st->execute();$alarms=$st->fetchAll(PDO::FETCH_ASSOC);$active=array_values(array_filter($alarms,fn($a)=>$a['status']==='active'));$history=$alarms;$totalActive=count($active);$totalHistory=count($history);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alarm Monitoring</title><link rel="stylesheet" href="../assets/css/variables.css?v=4"><link rel="stylesheet" href="../assets/css/common.css?v=4"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/alarm.css?v=4"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"></head><body><?php require_once '../includes/sidebar.php'; ?><main class="main-content alarm-page"><div class="container-fluid p-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="page-title">Alarm Monitoring</div><div class="subtitle">Real-time MikroTik Ether1 &amp; PPPoE bandwidth alarm monitoring</div></div><div class="text-end"><div class="refresh-text">Auto refresh 10 seconds</div><div><span class="badge bg-primary">NETWORK ALARM</span></div></div></div><div class="row g-4 mb-4"><div class="col-md-4"><div class="card stat-card"><div class="stat-title">Active Alarm</div><div id="activeAlarmCount" class="stat-value text-danger"><?= $totalActive ?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-title">Alarm History</div><div id="alarmHistoryCount" class="stat-value"><?= $totalHistory ?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-title">Monitoring</div><div id="monitoringStatus" class="stat-value text-success">CHECKING...</div></div></div></div><div class="card mb-4"><div class="card-header bg-white border-0 p-4"><h5 class="mb-0">🔴 Active Alarm</h5></div><div id="activeAlarmBody" class="card-body pt-0"><?php if(!$active): ?><div class="alert alert-success">🟢 Tidak ada alarm aktif. Semua kondisi jaringan normal.</div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Interface</th><th>Alarm</th><th>Severity</th><th>Value</th><th>Threshold</th><th>Message</th><th>Waktu</th></tr></thead><tbody><?php foreach($active as $a): ?><tr class="alarm-card"><td><strong><?=htmlspecialchars($a['interface_name'])?></strong></td><td><?=htmlspecialchars($a['alarm_type'])?></td><td><span class="badge <?= $a['severity']==='critical'?'badge-critical':'badge-warning' ?>"><?=strtoupper(htmlspecialchars($a['severity']))?></span></td><td><span class="value"><?=number_format((float)$a['value'],2)?> Mbps</span></td><td><?=number_format((float)$a['threshold'],2)?> Mbps</td><td class="message"><?=htmlspecialchars($a['message'])?></td><td><?=htmlspecialchars($a['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div><div class="card"><div class="card-header bg-white border-0 p-4"><h5 class="mb-0">📋 Alarm History</h5></div><div class="card-body pt-0"><div class="table-responsive"><table class="table"><thead><tr><th>Interface</th><th>Alarm</th><th>Severity</th><th>Value</th><th>Threshold</th><th>Status</th><th>Created</th><th>Resolved</th></tr></thead><tbody><?php foreach($history as $a): ?><tr><td><?=htmlspecialchars($a['interface_name'])?></td><td><?=htmlspecialchars($a['alarm_type'])?></td><td><span class="badge <?= $a['severity']==='critical'?'badge-critical':'badge-warning' ?>"><?=strtoupper(htmlspecialchars($a['severity']))?></span></td><td><?=number_format((float)$a['value'],2)?> Mbps</td><td><?=number_format((float)$a['threshold'],2)?> Mbps</td><td><span class="badge <?= $a['status']==='active'?'badge-active':'badge-resolved' ?>"><?=strtoupper(htmlspecialchars($a['status']))?></span></td><td><?=htmlspecialchars($a['created_at'])?></td><td><?=!empty($a['resolved_at'])?htmlspecialchars($a['resolved_at']):'-'?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></main><script>async function refreshAlarmCenter(){try{const r=await fetch('../api/alarm_status.php?nocache='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(!d.success)return;const c=document.getElementById('activeAlarmCount');if(c){c.textContent=Number(d.active)||0;c.classList.toggle('text-danger',Number(d.active)>0);c.classList.toggle('text-success',Number(d.active)===0)}const h=document.getElementById('alarmHistoryCount');if(h)h.textContent=Number(d.history||h.textContent)||0}catch(e){console.error('Alarm Center:',e)}}async function checkMonitoringStatus(){const e=document.getElementById('monitoringStatus');try{const r=await fetch('../api/traffic.php?nocache='+Date.now(),{cache:'no-store'});const d=await r.json();const on=d.status==='online';e.textContent=on?'ONLINE':'OFFLINE';e.classList.toggle('text-success',on);e.classList.toggle('text-danger',!on)}catch(x){e.textContent='OFFLINE';e.classList.remove('text-success');e.classList.add('text-danger')}}refreshAlarmCenter();checkMonitoringStatus();setInterval(refreshAlarmCenter,10000);setInterval(checkMonitoringStatus,10000);setInterval(()=>location.reload(),30000);</script><script src="../assets/js/pppoe_alarm_center.js?v=3"></script><script src="../assets/js/alarm_analytics.js?v=1"></script><script src="../assets/js/alarm_user_intelligence.js?v=1"></script><script src="../assets/js/pppoe_health.js?v=2"></script><script src="../assets/js/alarm_notification.js?v=5"></script><script src="../assets/js/app.js?v=1"></script></body></html>